  // 分类顺序（结果页按这个顺序列，稳定输出）
  var DREAM_CATS = Object.keys(DREAM);

  /** 精确取词 */
  function dreamOf(word) {
    var w = String(word == null ? '' : word).replace(/^\s+|\s+$/g, '');
    if (!w) return null;
    for (var i = 0; i < DREAM_CATS.length; i++) {
      var cat = DREAM_CATS[i];
      if (DREAM[cat][w]) return { 类别: cat, 词: w, 传统: DREAM[cat][w].传统, 心理: DREAM[cat][w].心理 };
    }
    return null;
  }

  /**
   * 从一句自然话里取梦象（「梦见一条大蛇」「梦到掉牙了」）。
   * 做法：先剥掉「做梦/梦见/梦到/梦里/梦/昨晚/今天」等壳词，再在剩余文本里找**最长命中**的词条
   * （长词优先：「掉牙」压过「牙」、「星星坠落」压过「星」），避免「梦见掉牙」被拆成「牙」。
   */
  var DREAM_SHELL = ['做梦', '梦见', '梦到', '梦里', '梦见了', '梦到了', '梦里出现', '梦', '昨晚', '昨天', '今天', '今早', '夜里', '晚上', '我', '了', '的', '一条', '一个', '一只', '有人', '很多'];
  function dreamMatch(text) {
    var t = String(text == null ? '' : text);
    DREAM_SHELL.forEach(function (w) { t = t.split(w).join(' '); });
    // 择优规则：① 词更长者优先（「掉牙」压「牙」）② 同长则**出现得更早**者优先
    // （「梦到会飞的猫」→ 先出现的「飞」优先，而不是按类别顺序被「猫」抢走）
    var best = null, bestLen = 0, bestPos = 1e9;
    DREAM_CATS.forEach(function (cat) {
      Object.keys(DREAM[cat]).forEach(function (k) {
        var pos = t.indexOf(k);
        if (pos < 0) return;
        if (k.length > bestLen || (k.length === bestLen && pos < bestPos)) {
          best = { 类别: cat, 词: k, 传统: DREAM[cat][k].传统, 心理: DREAM[cat][k].心理 };
          bestLen = k.length; bestPos = pos;
        }
      });
    });
    return best;
  }

  /** 某类全部词条（按词典内顺序） */
  function dreamList(cat) {
    var c = String(cat == null ? '' : cat).replace(/[类宫]$/, '');
    if (!DREAM[c]) return null;
    return Object.keys(DREAM[c]).map(function (k) {
      return { 词: k, 传统: DREAM[c][k].传统, 心理: DREAM[c][k].心理 };
    });
  }

  /** 全部类别 + 词数（「解梦」无参数时的总览） */
  function dreamCats() {
    return DREAM_CATS.map(function (c) { return { 类别: c, 词数: Object.keys(DREAM[c]).length }; });
  }
  /** 词条总数 */
  function dreamCount() {
    return DREAM_CATS.reduce(function (n, c) { return n + Object.keys(DREAM[c]).length; }, 0);
  }

  // ============ 占星骰子（12 宫 × 12 星座 × 10 行星）============
  var DICE_PLANET = ['太阳', '月亮', '水星', '金星', '火星', '木星', '土星', '天王星', '海王星', '冥王星'];
  var DICE_SIGN = ['白羊', '金牛', '双子', '巨蟹', '狮子', '室女', '天秤', '天蝎', '射手', '摩羯', '水瓶', '双鱼'];
  var DICE_HOUSE = ['1命宫', '2财帛', '3兄弟', '4田宅', '5子女', '6奴仆', '7夫妻', '8疾厄', '9迁移', '10官禄', '11朋友', '12玄秘'];
  function astroDice(pIdx, sIdx, hIdx) {
    var p = DICE_PLANET[((pIdx % 10) + 10) % 10];
    var s = DICE_SIGN[((sIdx % 12) + 12) % 12];
    var h = DICE_HOUSE[((hIdx % 12) + 12) % 12];
    return { 行星: p, 星座: s, 宫位: h, 解读: p + '（做什么）在' + s + '（怎样的方式）于' + h + '（哪个生活领域）' };
  }

  // ============ 观音灵签（100 签，签文见 guanyin-data.js）============
  var GUANYIN_COUNT = GY ? GY.count : 100;

  /**
   * 数据层用短字段（省字节），对外统一成长字段：给三个壳和搜索框用同一套名字，
   * 免得一处写「签名」一处写「名」对不上。
   */
  function gyInfo(r) {
    if (!r) return null;
    return {
      签号: r.号, 签名: r.名, 等级: r.等, 吉凶: r.吉凶, 宫位: r.宫,
      签诗: r.诗, 诗意: r.意, 解曰: r.解, 圣意: r.圣
    };
  }

  /** 按签号取签（1–100）；越界返回 null。签文原样返回，本文件不改一个字。 */
  function guanyinByNo(n) { return GY ? gyInfo(GY.byNo(n)) : null; }
  /** 按签名（典故名）取签，如「苏秦不第」「风送滕王阁」。 */
  function guanyinByName(s) { return GY ? gyInfo(GY.byName(s)) : null; }

  /**
   * 按日期抽签：字符串哈希 → 1–100，同日同签（可复现，不依赖随机数）。
   * 传统上「一签一问」，同日重复抽不作数，故产品层按「一日一签」处理。
   */
  function guanyinDraw(dateStr) {
    var s = String(dateStr || new Date().toISOString().slice(0, 10));
    var h = 0;
    for (var i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
    var n = (h % GUANYIN_COUNT) + 1;
    var r = guanyinByNo(n) || {};
    r.签号 = n;
    r.总签数 = GUANYIN_COUNT;
    r.注 = r.签名 ? '按日期定签，同日同签。' : '签文数据未加载。';
    return r;
  }

  // ============ 答案之书（随机文库，标非占卜）============
  var ANSWER_BOOK = ['顺其自然，自有安排。', '此刻正是时机。', '先静而后动。', '答案在行动里。', '放下，便见天地宽。', '信任你的直觉。', '慢一点，会更好。', '事缓则圆。', '山高自有客行路。', '心安处即是归途。'];
  function answerBook(seed) {
    var i;
    if (seed != null) i = ((seed % ANSWER_BOOK.length) + ANSWER_BOOK.length) % ANSWER_BOOK.length;
    else i = Math.floor(Math.random() * ANSWER_BOOK.length);
    return { 句: ANSWER_BOOK[i], 注: '随机激励文库（非占卜，纯随机）。' };
  }

